CREATE TABLE IF NOT EXISTS admin_users (id serial PRIMARY KEY, username text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'readonly' CHECK(role IN ('super_admin','content_reviewer','readonly')), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), last_login timestamptz);
CREATE TABLE IF NOT EXISTS analysis_records (id serial PRIMARY KEY, input_type text NOT NULL DEFAULT 'text' CHECK(input_type IN ('text','image')), input_text text, input_summary text NOT NULL, trust_score integer NOT NULL CHECK(trust_score BETWEEN 0 AND 100), risk_level text NOT NULL CHECK(risk_level IN ('low','medium','high','critical')), analysis_result jsonb, tactic_types text[], created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS drugs (id serial PRIMARY KEY, name text NOT NULL, approval_number text NOT NULL, manufacturer text NOT NULL, category text NOT NULL DEFAULT '藥品', approved_date text, ingredients text, claims text, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rhetoric_tags (id serial PRIMARY KEY, label text NOT NULL, tactic_type text NOT NULL, group_name text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','needs_revision')), region text, legal_basis text, historical_cases text, suggested_rewrite text, localized_content text, risk_override text, verification_status text, needs_review boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS url_queries (id serial PRIMARY KEY, url text NOT NULL, status text NOT NULL DEFAULT 'unknown' CHECK(status IN ('safe','suspicious','high_risk','unknown')), reason text NOT NULL, is_test boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_sessions (sid varchar PRIMARY KEY, sess json NOT NULL, expire timestamp(6) NOT NULL);
CREATE INDEX IF NOT EXISTS admin_sessions_expire_idx ON admin_sessions(expire);
